import {METRICS,clone,resonance,aggregateGear,gearDelta,skillWarnings,validateProfile as parseProfile,REGION_RULES} from './core.js';
import {hydrateRegistry,reconcileProfile,repoStats,checkAffix,normalizeAffix,AFFIX_LIMITS,affixCapacity,itemFitsSlot,makeAffix,selectGearItem} from './repo-policy.js';
const [DATA,REPO,MEDIA]=await Promise.all(['data.json','repo-items.json','wiki-media.json'].map(path=>fetch('./'+path).then(r=>{if(!r.ok)throw Error('โหลดข้อมูล repo ไม่สำเร็จ');return r.json()})));
hydrateRegistry(REPO);
const validateProfile=(input,base,catalog)=>reconcileProfile(parseProfile(input,base,catalog),REPO);
const BASE=reconcileProfile(DATA.baseline,REPO),CATALOG=DATA.catalog,KEY='taru-build-lab-v1';
let state=clone(BASE),saved=[],view='overview',gearFilter='',search='',pickerSlot=0,ownOnly=true,compareId='baseline',draft=null;
try{const cache=JSON.parse(localStorage.getItem(KEY)||'null');if(cache){state=validateProfile(cache.working,BASE,CATALOG);saved=(cache.saved||[]).slice(0,20).map(x=>({id:String(x.id),profile:validateProfile(x.profile,BASE,CATALOG)}));}}catch(e){console.warn('เริ่มด้วยชุดตั้งต้น:',e.message)}
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>new Intl.NumberFormat('en-US',{maximumFractionDigits:2}).format(n),colours={Attack:'#a47a58',Guard:'#6f9aae',Spirit:'#9383ad',Growth:'#82965b',Legendary:'#b89e52'};
const skillSlug={'Fan of Knives':'fan_knives',Elusion:'evasion'};
const titleMap={overview:['ทุกบิลด์ เริ่มจากการลอง','ปรับทีละจุด แล้วเทียบกับชุดที่คุณใช้จริง','ภาพรวมบิลด์'],equipment:['อุปกรณ์ที่เป็นคุณ','แก้ตัวเลข ออฟ และเอฟเฟกต์ของแต่ละชิ้นได้โดยตรง','อุปกรณ์และออฟ'],cards:['จัดสมุดให้เข้ากับเป้าหมาย','เห็นโบนัสภูมิภาค สายพันธุ์ และสีทันทีที่เปลี่ยนการ์ด','สมุดการ์ด'],skills:['ลองแต้ม ก่อนลงจริง','ตรวจแต้มและเงื่อนไขสกิล โดยเก็บบิลด์ต้นฉบับไว้เทียบ','สเตตัสและสกิล'],compare:['เห็นผลต่าง ก่อนตัดสินใจ','เปรียบเทียบโบนัสที่กรอกกับชุดเดิมหรือบิลด์ที่บันทึก','เปรียบเทียบบิลด์']};
titleMap.maps=['สำรวจโซนที่เพิ่มมา','แมพ Tidehaven และ Copperbell Arena · รายละเอียดจากการดึง Wiki ล่าสุด','แมพใหม่'];
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3400)}
function persist(){try{localStorage.setItem(KEY,JSON.stringify({version:1,working:state,saved}));$('#saveStatus').textContent='● บันทึกในเครื่องแล้ว';}catch{$('#saveStatus').textContent='บันทึกไม่ได้ · ส่งออกสำรอง';}}
function commit(){state=reconcileProfile(state,REPO);persist();render()}
function setView(v){view=v;gearFilter='';search='';render();window.scrollTo({top:0,behavior:'smooth'})}
function svg(kind){const paths={rapier:'<path d="M7 29 27 7M24 5l5 5M5 25l6 6M5 32l4-4"/><path d="M9 24c7-1 8 5 3 7"/>',dagger:'<path d="m6 29 9-9L27 5l-4 17-8 3M8 21l9 9M5 32l5-5"/>',hat:'<path d="M5 26c2-8 7-7 8-14l5-7 6 13 7 5-5 5-15 1Z"/><path d="m10 24 16-3"/>',mask:'<path d="M5 12 17 8l12 4-2 12-10 6-10-6Z"/><path d="m9 17 5 3m6 0 5-3m-12 7h8"/>',gem:'<path d="m7 9 20 0 4 8-14 15L3 17Z"/><path d="m7 9 6 8h8l6-8M13 17l4 15 4-15M3 17h28"/>',amulet:'<path d="M7 5c0 14 20 14 20 0M17 18v5"/><path d="m17 22 5 5-5 6-5-6Z"/>',armor:'<path d="m11 5 6 4 6-4 8 7-5 8-4-2v14H12V18l-5 2-5-8Z"/><path d="M17 10v18M12 22h10"/>',belt:'<path d="M3 12h28v14H3Z"/><path d="M12 9h10v20H12ZM15 16h4v6h-4"/>',ring:'<circle cx="17" cy="22" r="10"/><path d="m12 5 10 0 2 6-7 8-7-8ZM10 11h14M12 5l5 14 5-14"/>',boots:'<path d="M5 6h10v18l4 2v5H5ZM20 6h9v18l4 2v5H21V19"/><path d="M5 11h10M20 11h9"/>',hp:'<path d="M17 29 5 17C-1 8 12 2 17 11 23 2 35 8 29 17Z"/>',speed:'<path d="m20 4-12 16h9l-3 11 13-18h-9Z"/>'};return `<svg viewBox="0 0 34 36" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[kind]||paths.gem}</svg>`;}
function character(){return '<svg viewBox="0 0 130 210" aria-hidden="true"><path d="m34 87-13 83 45 23 43-24-17-83" fill="#4c4c5a"/><path d="m41 87-14 79 35-11 3-62" fill="#292e37"/><path d="m78 92 21 74-30-11" fill="#393f48"/><path d="m48 157-4 39 16 0 8-37M74 158l2 38h17l-7-43" fill="#34312f"/><path d="m44 192-4 10h23l-3-10m16 0-1 10h23l-7-10" fill="#252d29"/><path d="m49 96 30-2 12 48-45 4" fill="#778568"/><path d="m49 108 32 1m-35 16 41-3" stroke="#b5b59a" stroke-width="3"/><path d="m46 95-14 25 9 9 16-24m26-9 17 26-9 7-13-26" fill="#8e8068"/><path d="m33 122-10 16 8 6 12-16M94 123l10 18 8-6-12-15" fill="#c8ab88"/><path d="m30 145-17 32-3-1 14-35m82-3 16 34 3-2-11-37" stroke="#929b90" stroke-width="4"/><path d="m46 52 1 33 17 14 21-12 2-37" fill="#dbbb93"/><path d="m40 59 6-24 24-9 22 18-2 28-9-13-5-14-12 15-11-10-4 19" fill="#443d38"/><path d="m41 48 10-20 18-9 22 20-7-2-15-12-18 16" fill="#5c4b3d"/><path d="M53 69h7m12 0h7" stroke="#323d31" stroke-width="3"/><path d="m59 82 9 2 7-3" stroke="#a4785b" stroke-width="2"/><path d="m47 91 18 13 19-12-4 15-15 7-17-10" fill="#a39b78"/><path d="m47 142 42-3-1 12-44 4" fill="#403a32"/><rect x="61" y="141" width="13" height="12" rx="1" fill="#b29b5b"/><path d="m55 106 8 30m15-30-3 30" stroke="#a9ae8b" stroke-width="2"/></svg>';}
function crab(){return '<svg viewBox="0 0 160 110" aria-hidden="true"><path d="m49 68-22-8-9 13m30 6-22 4-5 12m90-25 22-9 10 12m-29 7 22 5 4 11" fill="none" stroke="#877f6a" stroke-width="7" stroke-linecap="round"/><path d="m51 59-18-13-12 7-11-17 9-16 8 13 8-5 8 17m68 14 16-17 13 5 11-19-10-13-5 15-9-5-7 19" fill="#b49870" stroke="#7b7967" stroke-width="2"/><path d="M40 75c0-30 17-45 41-45 25 0 40 16 40 45l-17 16H56Z" fill="#939b86" stroke="#6d7b64" stroke-width="2"/><path d="M54 68c0-16 12-27 27-27 14 0 28 11 28 27l-15 9H67Z" fill="#bac1a7"/><path d="m67 38 14-13 16 14-12 2" fill="#818c73"/><path d="m68 78-4-15m28 15 6-15" stroke="#625d4c" stroke-width="5" stroke-linecap="round"/><circle cx="64" cy="61" r="4" fill="#333e32"/><circle cx="98" cy="61" r="4" fill="#333e32"/><path d="m73 83 8 4 9-4" stroke="#70765e" fill="none" stroke-width="2"/></svg>';}
function cardGlyph(c){return ({Crab:'♋',Hound:'♜',Wisp:'✧',Skitter:'✳',Thornling:'♧',Remnant:'◇',Brute:'⬟',Harpy:'♜',Lurker:'◉',Sprout:'♧',Pebblit:'⬡',Warden:'♛'})[c.t]||'◇'}
function wikiImage(group,key,fallback,css=''){const entry=MEDIA[group]?.[key];if(!entry)return fallback;return '<span class="wiki-art '+css+'"><img class="wiki-sprite" src="'+esc(entry.src)+'" alt="'+esc(key.replaceAll('_',' '))+'" title="ภาพจาก Binder Town Wiki" loading="lazy"><span class="media-fallback">'+fallback+'</span></span>';}
function glyph(c){return wikiImage('mobs',c.s,cardGlyph(c),'card-sprite');}
document.addEventListener('error',e=>{if(e.target?.classList?.contains('wiki-sprite'))e.target.parentElement.classList.add('media-failed')},true);
function bonusLabel(s){const m=METRICS[s.key]||[s.key,''];return `${m[0]} ${s.value>=0?'+':''}${fmt(s.value)}${m[1]}`}
function currentRes(){return resonance(state,CATALOG)}
function regionPills(res){return res.active.filter(x=>x.kind==='Region').map(x=>`<span class="resonance-pill">${esc(x.name)}</span>`).join('')}
function render(){const names=titleMap[view];$('#pageTitle').innerHTML=esc(names[0])+'<span>.</span>';$('#pageSubtitle').textContent=names[1];$('#crumb').textContent=names[2];$('#buildName').value=state.name;$('#nav').querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#content').innerHTML=sourceBanner()+({overview:overview,equipment:equipment,cards:cards,skills:skills,compare:compare,maps:mapsView})[view]();}
function sourceBanner(){const mapped=state.gear.filter(g=>g.repoStatus==='matched').length;const conflicts=state.gear.reduce((n,g)=>n+g.repoIssues.length,0);return '<div class="repo-banner"><div><strong>ฐานข้อมูล: repo snapshot</strong><span>ข้อมูล Wiki '+esc(DATA.repoCrawled)+'</span></div><a href="'+esc(DATA.sources.commit)+'" target="_blank" rel="noreferrer">commit '+REPO.ref.slice(0,7)+' ↗</a><button class="quiet" data-gaps>ข้อมูลที่ยังขาด ↗</button><span class="capsule">จับคู่ '+mapped+'/11 ช่อง · ตรวจสอบ '+conflicts+' จุด</span></div>';}
function showDataGaps(){const c=DATA.coverage;$('#gapContent').innerHTML='<p>ดึงสด '+c.liveCapturePages+' หน้า ล่าสุด '+esc(c.latestCapture)+' · ใช้ '+c.liveCredits+' เครดิต Firecrawl</p><p>รวมแมพ Tidehaven/Copperbell Arena ของใหม่ 119 ชิ้น อุปกรณ์เดิมของ Taru มอน Shellforge และกติกาออฟแล้ว</p><p><strong>'+c.olderDetails+' รายละเอียดเดิม</strong> ยังเป็น 7 พ.ย. เช่นสกิล Rogue และการ์ดเดิมบางใบ<br><strong>'+fmt(c.notFetched)+' URL</strong> ยังไม่มีรายละเอียด หลายหน้าตั้งใจข้ามตามขอบเขต Tier 10<br><strong>'+c.conflicts+' จุด</strong> หน้ารวมกับรายละเอียดของอาวุธเดิมให้ค่าต่างกัน จึงติดป้ายรอยืนยัน</p><p>ไม่จำเป็นต้องดึงไอเท็ม Tier 1–9 และแฟชั่นทั้งหมด ส่วนที่ไม่ทราบค่าไม่ใช้ 0 แทน</p><p><a href="'+esc(DATA.sources.gaps)+'" target="_blank" rel="noreferrer">รายการข้อมูลที่ยังขาด ↗</a> · <a href="'+esc(DATA.sources.queue)+'" target="_blank" rel="noreferrer">รายการ URL ที่ต้องดึง ↗</a></p>';$('#gapDialog').showModal();}
function repoBadge(g){return '<div class="repo-item-status">'+(g.sourceUrl?'<a href="'+esc(g.sourceUrl)+'" target="_blank" rel="noreferrer">'+esc(g.itemSlug)+' ↗</a><span>รายละเอียด '+esc(g.sourceLastCrawled||'ไม่ทราบวันที่')+(g.sourceLastCrawled==='2026-11-07'?' · ยังไม่ดึงใหม่':'')+'</span>':'<span class="warning-badge">ไม่พบใน repo</span>')+(g.repoIssues.length?'<p>'+g.repoIssues.map(esc).join('<br>')+'</p>':'<p class="repo-ok">ค่าพื้นฐาน/ตีบวกจาก repo · ออฟผู้เล่นผ่านช่วงที่กำหนด</p>')+'</div>';}
function metric(label,value,unit,icon,foot,highlight=false,warning=''){return `<div class="metric ${highlight?'highlight':''}"><div class="metric-top"><span>${label}</span>${svg(icon)}</div><div class="metric-value">${value}<span>${unit}</span></div><div class="metric-bottom"><span>${foot}</span>${warning?`<span class="metric-warn">${warning}</span>`:''}</div><div class="progress"><span style="width:${highlight?'72':'55'}%"></span></div></div>`;}
function gearMini(id){const g=state.gear.find(x=>x.id===id);return `<button class="gear-mini ${g.enabled?'':'disabled'}" data-edit="${g.id}"><span class="slot-icon">${wikiImage('items',g.itemSlug,svg(g.icon),'item-sprite')}</span><span class="mini-copy"><small>${esc(g.slot)}</small><strong>${esc(g.name)}</strong></span><span class="plus">+${g.enchant}</span></button>`;}
function overview(){const r=currentRes(),o=BASE.observed,changed=gearDelta(state,BASE).filter(x=>x.delta!==0).length,attrsChanged=Object.keys(BASE.attrs).some(k=>BASE.attrs[k]!==state.attrs[k]);return `<div class="section-label"><div><h2>ค่าต่อสู้ตั้งต้น</h2><p>คัดจากภาพในเกม · ค่าชุดเดิม ไม่ใช่ผลคำนวณของบิลด์ทดลอง</p></div><span class="capsule">PLAYER SNAPSHOT / DRAW­DY</span></div><div class="metrics">${metric('พลังโจมตี',fmt(o.atk),'ATK','rapier','เรเปียร์ · Lv 108')}${metric('พลังชีวิต',fmt(o.hp),'HP','hp','ดูดเลือด 9% · ฟื้น HP 52/s')}${metric('โอกาสคริติคอล',fmt(o.crit),'%','gem','ดาเมจคริ 293%',false,'เลยจุดลดผล')}${metric('ความเร็วโจมตี',fmt(o.aps),'ครั้ง/s','speed','ลด CD สกิล 33.3%',true)}</div><div class="overview-grid"><section class="panel"><div class="panel-head"><div><h2>อุปกรณ์ที่สวมใส่</h2><p>แตะชิ้นที่ต้องการ เพื่อแก้ไขและทดลองออฟ</p></div><button class="text-button" data-go="equipment">ดูทั้งหมด ↗</button></div><div class="outfit"><div class="outfit-col">${['head','face','mouth','neck','armor'].map(gearMini).join('')}</div><div class="character-stage"><div class="ground"></div>${wikiImage('classes','rogue',character(),'class-art')}<span>ROGUE</span><div class="character-level">LV.108 / JOB 50</div></div><div class="outfit-col">${['weapon','offhand','ring1','ring2','boots'].map(gearMini).join('')}</div></div><div class="tinker-row"><span>◇</span><span><strong>Tinker ${state.gear.filter(g=>g.enabled&&g.set==='Tinker').length}/4</strong> · โบนัสเมื่อใส่ครบ 2 ชิ้น: มีโอกาสลด CD ครึ่งหนึ่ง</span></div></section><section class="panel"><div class="panel-head"><div><h2>เป้าหมายของบิลด์</h2><p>Shellforge Basin · ฟาร์มออนไลน์</p></div><span class="capsule">PVE</span></div><div class="panel-body">${targetPanel()}</div></section></div><section class="panel" style="margin-top:19px"><div class="panel-head"><div><h2>สมุดการ์ด</h2><p>${r.slots}/9 ช่อง · Spirit Load ${r.load}/18 ${r.load>18?'⚠ เกินภาระ':''}</p></div><button class="text-button" data-go="cards">จัดสมุดการ์ด ↗</button></div><div class="mini-card-row">${state.cards.map((slug,i)=>miniCard(slug,i)).join('')}</div><div class="card-panel-foot">${regionPills(r)}<span class="dot-sep">·</span><span>${r.active.length} โบนัสชุดทำงาน</span></div></section><div class="bottom-grid"><section class="panel"><div class="panel-head"><div><h2>ลองบิลด์ที่คุยกันไว้</h2><p>เปลี่ยนเฉพาะชุดการ์ด · กดคืนค่าชุดเดิมได้เสมอ</p></div></div><div class="experiment-card"><div class="experiment-symbol">♧</div><div class="experiment-copy"><strong>คู่ Thornling</strong><p>Shrine → Thornling · Lamp → Shard Thornling</p></div><button class="button preset" data-preset="thorn">ลองชุดนี้ ↗</button></div><div class="experiment-card"><div class="experiment-symbol" style="color:#7192a3;background:#edf3f5">♋</div><div class="experiment-copy"><strong>ยืนตี Mini-boss</strong><p>ชุดเดิม เปลี่ยน Brass Mimic → Plate Turtle</p></div><button class="button preset" data-preset="survival">ลองชุดนี้ ↗</button></div></section><section class="panel"><div class="panel-head"><div><h2>สิ่งที่เปลี่ยนจากชุดเดิม</h2><p>รวมโบนัสที่กรอก แยกจากค่าต่อสู้ในเกม</p></div><button class="text-button" data-go="compare">เทียบละเอียด ↗</button></div><div class="panel-body"><div class="source-item"><strong>โบนัสอุปกรณ์ที่ต่าง</strong><span>${changed} รายการ</span></div><div class="source-item"><strong>การ์ดที่เปลี่ยน</strong><span>${state.cards.filter((x,i)=>x!==BASE.cards[i]).length} ช่อง</span></div><div class="source-item"><strong>สเตตัสพื้นฐาน</strong><span>${attrsChanged?'มีการทดลองปรับ':'ตรงกับชุดเดิม'}</span></div><div class="source-item"><strong>ตัวเลข ATK / HP รวม</strong><a href="#" data-method>ดูขอบเขตการคำนวณ ↗</a></div></div></section></div><div class="notice"><strong>ฐาน repo ก่อน:</strong> ชิ้นที่หาไม่พบ อาวุธรองที่ยังไม่ยืนยัน และออฟนอกช่วง repo จะไม่นำมารวมโบนัส · ค่าต่อสู้ด้านบนยังเป็นภาพบิลด์ผู้เล่น ไม่ใช่ค่าคำนวณจาก repo</div>`;}
function targetPanel(){const t=DATA.targets.find(x=>x.id===state.target)||DATA.targets[0];return `<select id="targetSelect" class="target-select" aria-label="มอนเป้าหมาย">${DATA.targets.map(x=>`<option value="${x.id}" ${x.id===t.id?'selected':''}>${esc(x.name)} — ${esc(x.tag)}</option>`).join('')}</select><div class="monster-art"><span class="monster-tag">${esc(t.tag.split(' · ')[0])}</span>${wikiImage('mobs',t.id,crab(),'target-sprite')}</div><div class="target-stats"><div><label>MAX HP</label><strong>${fmt(t.hp)}</strong></div><div><label>DEF</label><strong>${t.def}</strong></div><div><label>วิญญาณพื้นฐาน</label><strong>${t.spirit}</strong></div></div><div class="weakness-row"><span>แพ้ธาตุ</span><strong>${esc(t.weakness)}</strong></div><div class="weakness-row"><span>ต้านธาตุ</span><strong style="color:#a7886d">${esc(t.resist)}</strong></div><div class="target-note">${esc(t.note)}</div><div class="target-footer"><span>ข้อมูลพื้นฐานก่อนตัวคูณ · ดึง 2026-11-10</span><a href="${DATA.sources.wiki}mob/${t.id}" target="_blank" rel="noreferrer">ดู Wiki ↗</a></div>`;}
function miniCard(slug,index){const c=CATALOG.find(x=>x.s===slug);if(!c)return '';const stars=state.cardStars?.[slug]||5;return `<button class="mini-card" style="--card-color:${colours[c.c]}" data-card-slot="${index}" title="${esc(c.n)}: ${esc(stars===1?c.e1:c.e5)}"><div class="card-glyph">${glyph(c)}</div><div class="card-stars">${'★'.repeat(stars)}</div><strong>${esc(c.n)}</strong><small>◆ ${c.l}</small></button>`;}
function equipment(){const items=state.gear.filter(g=>(!gearFilter||g.rarity===gearFilter)&&(!search||(g.name+' '+g.slot+' '+g.affixes.map(a=>a.name).join(' ')).toLowerCase().includes(search.toLowerCase())));return `<div class="notice"><strong>ใช้ repo เป็นฐาน:</strong> รหัสไอเท็ม ชื่อ ค่าพื้นฐาน และค่าตีบวกดึงจากตาราง repo · ออฟที่กรอกจะตรวจชื่อ ชนิดโบนัส และช่วงค่า ไม่เดาค่าจากภาพที่ขัดแย้ง</div><div class="toolbar"><input class="search-input" id="gearSearch" placeholder="ค้นหาอุปกรณ์หรือออฟ…" value="${esc(search)}" aria-label="ค้นหาอุปกรณ์">${['','Epic','Magic'].map(f=>`<button class="filter ${gearFilter===f?'active':''}" data-gear-filter="${f}">${f||'ทุกชิ้น'}</button>`).join('')}<span class="muted" style="margin-left:auto;font-size:10px">${items.length} ชิ้น</span></div><div class="equipment-grid">${items.map(g=>`<article class="equipment-card ${g.enabled?'':'off'}"><div class="equip-header"><div class="slot-icon">${wikiImage('items',g.itemSlug,svg(g.icon),'item-sprite')}</div><div><small>${esc(g.slot)} · ${esc(g.rarity)} · Lv ${g.level}</small><strong>${esc(g.name)}</strong>${g.uncertain?'<span class="warning-badge">ตรวจสอบตำแหน่ง</span>':''}</div><span class="plus">+${g.enchant}</span></div>${repoBadge(g)}<div class="equip-values">${g.stats.map(s=>`<span class="stat-chip">${esc(bonusLabel(s))}</span>`).join('')}</div><div class="affix-list">${g.affixes.map(a=>`<div class="affix-line"><span class="tier ${a.tier==='T7'?'t7':''}">${a.tier}</span><span>${a.sourceStatus==='conflict'?'<span class="conflict-text">'+esc(bonusLabel(a))+' · ไม่รวม</span>':['trigger','reference'].includes(a.key)?'เอฟเฟกต์อ้างอิง':esc(bonusLabel(a))}</span><span class="affix-name" title="${esc(a.name)}">${esc(a.name)}</span></div>`).join('')}</div><div class="equip-foot"><label class="switch-label"><input type="checkbox" data-toggle-gear="${g.id}" ${g.enabled?'checked':''}> ใช้ในบิลด์</label><button class="text-button" data-edit="${g.id}">แก้ไขชิ้นนี้ ↗</button></div></article>`).join('')}</div>${items.length?'':'<div class="empty-state">ไม่พบอุปกรณ์ที่ค้นหา</div>'}`;}
function cards(){const r=currentRes();return `<div class="section-label"><div><h2>การ์ดในบิลด์ ${r.slots}/9 <span class="muted">· Load ${r.load}/18</span></h2><p>เปลี่ยนได้จากการ์ดในคลัง หรือเปิดแค็ตตาล็อกทั้งหมดเพื่อทดลอง</p></div><div class="toggle-group"><button data-night="false" class="${state.night?'':'active'}">☀ กลางวัน</button><button data-night="true" class="${state.night?'active':''}">☾ กลางคืน</button></div></div>${r.load>18?'<div class="notice"><strong>เกินภาระ:</strong> ชุดนี้ใส่จริงไม่ได้ที่ Load 18</div>':''}<div class="cards-layout"><div class="equipped-cards">${state.cards.map((slug,i)=>fullCard(slug,i)).join('')}</div><aside class="panel sticky-panel"><div class="panel-head"><div><h2>Resonance</h2><p>${r.active.length} โบนัสชุดทำงานพร้อมกัน</p></div><span>✧</span></div><div class="panel-body">${r.active.map(x=>`<div class="resonance-row"><span class="count">${x.count}/${x.threshold}</span><strong>${esc(x.name)}</strong><small>${esc(x.effect)}</small></div>`).join('')}${!r.active.length?'<p class="note-small">ยังไม่มีชุดที่ครบเงื่อนไข</p>':''}<div class="measurement-box">สีเดียวกันต้องมี ★3+ 3 ใบ · ใบซ้ำไม่เพิ่มจำนวนชุด<br>ค่าการ์ด ★2–★4 ไม่ทราบ จึงให้เลือกทดลองเฉพาะ ★1 / ★5</div><div class="notice" style="margin-bottom:0">โบนัสวิญญาณไม่เท่ากับเรทดรอปไอเท็ม และยังไม่ทราบผลของวิญญาณเกิน 100% ต่อ Mini-boss</div></div></aside></div>`;}
function fullCard(slug,i){const c=CATALOG.find(x=>x.s===slug),stars=state.cardStars?.[slug]||5,owned=(DATA.inventory[slug]?.taru||0)+(DATA.inventory[slug]?.bank||0),copyIndex=state.cards.slice(0,i).filter(x=>x===slug).length,nightCard=['Wisp','Remnant','Horror','Lurker'].includes(c.t),unknownTime=['shrine_firefly','lamp_wisp','mirror_merchant'].includes(slug);return `<article class="full-card" style="--card-color:${colours[c.c]}"><div class="full-card-head"><div class="card-glyph">${glyph(c)}</div><div><strong>${esc(c.n)}</strong><small>${esc(c.r)} · ${esc(c.t)} · ${esc(c.c)}</small></div></div><div class="card-effect">${esc(stars===1?c.e1:c.e5)}</div><div class="note-small">${copyIndex?`Echo ใบที่ ${copyIndex+1}: ${copyIndex===1?'50%':copyIndex===2?'25%':'ไม่มีผล'}`:unknownTime?`เวลา: ${state.night?'×1.4 กลางคืน':'×0.85 กลางวัน'} (ตามบันทึกยืนยันใน repo)`:nightCard?'การ์ดกลางคืน · แสดงค่า Wiki ก่อนตัวคูณ':'ค่า Wiki ก่อนตัวคูณตามเวลา'}</div><div class="full-card-foot"><span>◆ ${c.l} ${owned?'· มีในคลัง':'· สมมติ ยังไม่มี'}</span><select data-card-stars="${slug}" aria-label="ดาว ${esc(c.n)}"><option value="1" ${stars===1?'selected':''}>★1</option><option value="5" ${stars===5?'selected':''}>★5</option></select><button class="button" data-card-slot="${i}">เปลี่ยน ↗</button></div></article>`;}
function skills(){const total=state.skills.reduce((s,x)=>s+x.level,0),budget=BASE.skills.reduce((s,x)=>s+x.level,0),warn=skillWarnings(state,BASE);return `<div class="section-label"><div><h2>แต้มสเตตัสพื้นฐาน</h2><p>แต้มที่ลงเอง 0–99 แยกจากโบนัสอุปกรณ์ · ยังไม่คำนวณสเตตัสรวมใหม่</p></div><span class="capsule">BASE POINTS</span></div><div class="attrs-grid">${Object.entries(state.attrs).map(([k,n])=>`<div class="attr-card"><label for="attr-${k}">${k.toUpperCase()}</label><input id="attr-${k}" type="number" min="0" max="99" step="1" data-attr="${k}" value="${n}"><small>ชุดเดิม ${BASE.attrs[k]} · ในภาพรวม ${BASE.observedAttrs[k]}</small></div>`).join('')}</div><div class="section-label"><div><h2>Skill tree</h2><p>ใช้ ${total}/${budget} แต้มเทียบชุดตั้งต้น · รวมสกิลเริ่มต้นฟรีตามภาพ</p></div><span class="capsule">JOB LV.50</span></div>${warn.length?`<div class="notice"><strong>เงื่อนไขที่ยังไม่ครบ:</strong><br>${warn.map(esc).join('<br>')}</div>`:''}<div class="skills-grid">${['Assassin','Trickery','Shadow'].map(branch=>{const list=state.skills.filter(x=>x.branch===branch),sum=list.reduce((s,x)=>s+x.level,0);return `<section class="panel"><div class="panel-head"><div><h2>${branch}</h2><p>${sum} แต้ม · Trait ${sum>=10?'เปิดได้':'ต้องครบ 10'} · Mastery ${Math.min(sum,20)}/20</p></div><span>✧</span></div><div class="panel-body">${list.map(s=>{const i=state.skills.indexOf(s),isActive=s.max===10||['Fade','Adrenaline'].includes(s.name);return `<div class="skill-row"><div class="skill-top"><strong><span class="skill-art">${wikiImage('skills',skillSlug[s.name]||s.name.toLowerCase().replaceAll(' ','_'),'✧')}</span>${esc(s.name)}</strong><div class="skill-control"><button class="stepper" data-skill="${i}" data-step="-1" aria-label="ลด ${esc(s.name)}" ${s.level===0?'disabled':''}>−</button><span>${s.level}/${s.max}</span><button class="stepper" data-skill="${i}" data-step="1" aria-label="เพิ่ม ${esc(s.name)}" ${s.level===s.max?'disabled':''}>+</button></div></div>${isActive?`<select class="evo-select" data-evo="${i}" aria-label="Evolution ${esc(s.name)}"><option value="" ${!s.evo?'selected':''}>ยังไม่เลือก Evolution</option><option value="A" ${s.evo==='A'?'selected':''}>Evolution A</option><option value="B" ${s.evo==='B'?'selected':''}>Evolution B</option></select>`:''}<div class="skill-meter"><span style="width:${s.level/s.max*100}%"></span></div></div>`;}).join('')}</div></section>`;}).join('')}</div><div class="notice"><strong>ขอบเขต:</strong> ตรวจแต้ม เงื่อนไขสกิลก่อนหน้า Trait และ Mastery เท่านั้น ยังไม่เปลี่ยนผลรวม ATK/HP หรือจำลองพฤติกรรม AUTO ตามสกิลที่เลือก</div>`;}
function compare(){const other=compareId==='baseline'?BASE:saved.find(x=>x.id===compareId)?.profile||BASE,deltas=gearDelta(state,other),nonzero=deltas.filter(x=>x.delta),a=resonance(state,CATALOG),b=resonance(other,CATALOG),lost=b.active.filter(x=>!a.active.some(y=>y.id===x.id&&y.name===x.name)),gained=a.active.filter(x=>!b.active.some(y=>y.id===x.id&&y.name===x.name));return `<div class="section-label"><div><h2>บิลด์ทดลอง เทียบกับ</h2><p>ผลต่างโบนัสที่กรอก ไม่รวมสูตรคำนวณสเตตัสสุดท้าย</p></div><select class="compare-selector" id="compareSelect" aria-label="เลือกบิลด์อ้างอิง"><option value="baseline" ${compareId==='baseline'?'selected':''}>Taru · ชุดเดิมจากภาพ</option>${saved.map(x=>`<option value="${esc(x.id)}" ${compareId===x.id?'selected':''}>${esc(x.profile.name)}</option>`).join('')}</select></div><div class="delta-summary"><span>อุปกรณ์ต่าง ${state.gear.filter((g,i)=>JSON.stringify(g)!==JSON.stringify(other.gear[i])).length} ชิ้น</span><span>การ์ดต่าง ${state.cards.filter((x,i)=>x!==other.cards[i]||(state.cardStars?.[x]||5)!==(other.cardStars?.[x]||5)).length} ช่อง</span><span>โบนัสต่าง ${nonzero.length} รายการ</span></div><div class="compare-layout"><section class="panel"><div class="panel-head"><h2>โบนัสอุปกรณ์</h2><span class="capsule">RAW MODIFIERS</span></div><table class="data-table"><thead><tr><th>โบนัส</th><th>อ้างอิง</th><th>ทดลอง</th><th>ผลต่าง</th></tr></thead><tbody>${(nonzero.length?nonzero:deltas.filter(x=>['atk','atkPct','hp','hpPct','crit','critDamage','cdr','ccDamage'].includes(x.key))).map(x=>`<tr><td>${METRICS[x.key][0]}${METRICS[x.key][1]?' (%)':''}</td><td>${fmt(x.before)}</td><td>${fmt(x.after)}</td><td class="delta-${x.delta>0?'positive':x.delta<0?'negative':'zero'}">${x.delta>0?'+':''}${fmt(x.delta)}</td></tr>`).join('')}</tbody></table><div class="panel-body"><div class="measurement-box">ผลต่างค่า % คือจุดเปอร์เซ็นต์ของโบนัสอุปกรณ์ ไม่ใช่ % ที่ DPS/HP เพิ่มจริง · ไม่รวมการ์ด สกิล หรือ soft cap</div></div></section><section class="panel"><div class="panel-head"><h2>โบนัสชุดที่เปลี่ยน</h2><span class="capsule">RESONANCE</span></div><div class="panel-body">${gained.map(x=>`<div class="resonance-row"><strong class="delta-positive">＋ ${esc(x.name)}</strong><small>${esc(x.effect)}</small></div>`).join('')}${lost.map(x=>`<div class="resonance-row"><strong class="delta-negative">− ${esc(x.name)}</strong><small>${esc(x.effect)}</small></div>`).join('')}${!gained.length&&!lost.length?'<div class="empty-state">โบนัสชุดยังเหมือนบิลด์อ้างอิง</div>':''}<div class="section-label"><h3>สเตตัสที่ลงเอง</h3></div>${Object.keys(state.attrs).map(k=>`<div class="source-item"><strong>${k.toUpperCase()}</strong><span>${other.attrs[k]} → ${state.attrs[k]} <b class="delta-${state.attrs[k]>other.attrs[k]?'positive':state.attrs[k]<other.attrs[k]?'negative':'zero'}">(${state.attrs[k]-other.attrs[k]>0?'+':''}${state.attrs[k]-other.attrs[k]})</b></span></div>`).join('')}</div></section></div><div class="section-label"><div><h2>การ์ดที่เปลี่ยนรายช่อง</h2><p>แยกเอฟเฟกต์การ์ดออกจากโบนัสชุด · ไม่เดาตัวคูณรวม</p></div></div><section class="panel"><table class="data-table"><thead><tr><th>ช่อง</th><th>อ้างอิง</th><th>ทดลอง</th></tr></thead><tbody>${state.cards.map((s,i)=>{const c=CATALOG.find(c=>c.s===s),prev=CATALOG.find(c=>c.s===other.cards[i]);if(s===other.cards[i]&&(state.cardStars?.[s]||5)===(other.cardStars?.[s]||5))return '';return `<tr><td>${i+1}</td><td>${esc(prev?.n||'ว่าง')}<p class="note-small">${esc((other.cardStars?.[prev?.s]||5)===1?prev?.e1:prev?.e5)}</p></td><td>${esc(c.n)}<p class="note-small">${esc((state.cardStars?.[s]||5)===1?c.e1:c.e5)}</p></td></tr>`;}).join('')||'<tr><td colspan="3" class="muted">ยังไม่มีการเปลี่ยนการ์ด</td></tr>'}</tbody></table></section><div class="section-label"><h2>บิลด์ที่บันทึกไว้</h2><span class="capsule">${saved.length}/20</span></div><div class="saved-builds">${saved.map(x=>`<div style="display:flex;gap:3px"><button class="button" data-load="${esc(x.id)}">↗ ${esc(x.profile.name)}</button><button class="button" data-delete-build="${esc(x.id)}" aria-label="ลบบิลด์ ${esc(x.profile.name)}">×</button></div>`).join('')||'<p class="note-small">กด “บันทึกบิลด์นี้” เพื่อเก็บชุดทดลองไว้เทียบภายหลัง</p>'}</div>`;}
function options(key){return Object.entries(METRICS).map(([k,v])=>`<option value="${k}" ${k===key?'selected':''}>${esc(v[0])}${v[1]?' (%)':''}</option>`).join('')}
function openEditor(id){draft=clone(state.gear.find(g=>g.id===id));renderEditor();$('#editor').showModal()}
// Item and affix editor.
function gearItemOptions(g){return Object.values(REPO.items).filter(item=>itemFitsSlot(item,g.id,REPO)).sort((a,b)=>Number(b.slug.includes('_tide'))-Number(a.slug.includes('_tide'))||a.name.localeCompare(b.name,'th'));}
function changeDraftItem(slug){syncDraft();draft=selectGearItem(draft,slug,REPO);renderEditor();}
function addDraftAffix(){syncDraft();if(draft.affixes.length>=affixCapacity(draft.rarity)){toast('ครบจำนวนออฟของความหายากนี้แล้ว');return}const rule=affixChoices(draft,REPO).find(r=>r.kind!=='trigger')||affixChoices(draft,REPO)[0];if(!rule){toast('ไม่มีออฟที่เพิ่มได้ตามกติกา');return}draft.affixes.push(makeAffix(rule));renderEditor();}
function affixChoices(g,registry,index=-1){const item=registry.items[g.itemSlug];if(!item)return [];const others=g.affixes.filter((a,i)=>i!==index).map(a=>item.allowedAffixes.find(r=>r.norm===normalizeAffix(a.name))).filter(Boolean);const prefixes=others.filter(r=>!/^of /i.test(r.name)).length,suffixes=others.filter(r=>/^of /i.test(r.name)).length;return item.allowedAffixes.filter(r=>!others.some(a=>a.family===r.family)&&(/^of /i.test(r.name)?suffixes<3:prefixes<2));}
function affixSelectMarkup(g,affix,index){const rules=affixChoices(g,REPO,index),rule=rules.find(r=>r.norm===normalizeAffix(affix.name)),audit=checkAffix(affix,REPO.items[g.itemSlug],REPO,g);return `<div class="affix-choice-row"><div class="affix-choice-inputs"><select data-affix-choice="${index}" aria-label="เลือกออฟ ${index+1}">${!rule?`<option value="" selected>ตรวจสอบ: ${esc(affix.name)}</option>`:''}${rules.map(r=>`<option value="${esc(r.norm)}" ${r.norm===rule?.norm?'selected':''}>${esc(r.tier+' · '+r.name)}</option>`).join('')}</select><input type="number" step="any" value="${affix.value}" ${['trigger','reference'].includes(affix.key)?'disabled':''} data-draft-type="affixes" data-row="${index}" data-field="value" aria-label="ค่าออฟ ${index+1}"><button class="remove-row" data-remove-row="affixes" data-row="${index}" aria-label="ลบออฟ ${index+1}">×</button></div><p class="note-small ${audit.status==='conflict'?'conflict-text':''}">${rule?esc(rule.minText+' → '+rule.maxText):esc(audit.message)}${rule&&['trigger','reference'].includes(affix.key)?' · แสดงอ้างอิง ไม่รวมเป็นโบนัสถาวร':rule?' · '+esc(audit.message):''}</p></div>`;}
function renderEditor(){const g=draft,item=REPO.items[g.itemSlug],choices=gearItemOptions(g);$('#editorContent').innerHTML=`<div class="dialog-head"><div><div class="eyebrow">EQUIPMENT EDITOR · ${esc(g.slot)}</div><h2>เลือกอุปกรณ์และออฟ</h2>${repoBadge(g)}</div><button class="icon-button close-dialog" aria-label="ปิด">×</button></div><div class="form-grid"><div class="form-field full"><label for="editItemSearch">ค้นหาอุปกรณ์ Tier 10 · Rogue</label><input id="editItemSearch" placeholder="พิมพ์ชื่อหรือรหัส เช่น Tidebound, rapier" aria-label="ค้นหาอุปกรณ์"><label for="editItem">เลือกอุปกรณ์ช่องนี้ (${choices.length} ชิ้น)</label><select id="editItem">${choices.map(i=>`<option value="${esc(i.slug)}" ${i.slug===g.itemSlug?'selected':''}>${esc(i.name)} · Lv ${i.level}${i.slug.includes('_tide')?' · ใหม่ Tidebound':''}</option>`).join('')}</select></div><div class="form-field"><label for="editEnchant">ระดับตีบวก</label><input id="editEnchant" type="number" min="0" max="15" step="1" value="${g.enchant}"></div><div class="form-field"><label for="editRarity">ความหายาก / จำนวนออฟ</label><select id="editRarity">${Object.entries(AFFIX_LIMITS).map(([rarity,count])=>`<option ${g.rarity===rarity?'selected':''} value="${rarity}">${rarity} · ${count} ออฟ</option>`).join('')}</select></div><div class="form-field"><label for="editSet">ชื่อเซ็ต (บันทึกอ้างอิง)</label><input id="editSet" value="${esc(g.set)}" placeholder="เช่น Tinker"></div><div class="form-field"><label for="editCoefficient">ตัวคูณโบนัสในบิลด์ทดลอง</label><input id="editCoefficient" type="number" min="0" max="1" step="0.1" value="${g.coefficient??1}"></div></div>${g.id==='offhand'?'<div class="notice">ต้องยืนยันว่าใช้มือรองนี้ร่วมกับอาวุธหลักได้จริง<br><label class="switch-label"><input type="checkbox" id="editRoleConfirmed" '+(g.roleConfirmed?'checked':'')+'> รวมมือรองในบิลด์ทดลอง (สมมติฐานผู้ใช้)</label></div>':''}<div class="editor-section"><h3>สเตตัสจาก Wiki / repo</h3><span class="note-small">เปลี่ยนตามไอเท็มและระดับตีบวก</span></div><div class="stat-reference">${g.stats.map(s=>`<span>${esc(bonusLabel(s))}</span>`).join('')}</div>${item?.referenceStats?.length?'<p class="note-small">เอฟเฟกต์อ้างอิง: '+item.referenceStats.map(esc).join(' · ')+'</p>':''}<div class="editor-section"><h3>เลือกออฟ ${g.affixes.length}/${affixCapacity(g.rarity)}</h3><button class="text-button" data-add-row="affixes" ${g.affixes.length>=affixCapacity(g.rarity)?'disabled':''}>＋ เพิ่มออฟ</button></div><p class="note-small">เลือกเฉพาะออฟในพูลของชิ้นนี้ · ไม่ซ้ำตระกูล · สูงสุด 2 Prefix / 3 Suffix · ค่า Focused ตรวจตาม Magic 1–2 แถว</p>${g.affixes.map((a,i)=>affixSelectMarkup(g,a,i)).join('')}<div class="form-field"><label for="editNotes">เอฟเฟกต์ / Infusion / Inscription / หมายเหตุ</label><textarea id="editNotes">${esc(g.notes)}</textarea></div><div class="dialog-actions"><button class="text-button" id="restorePiece">↺ คืนค่าชิ้นนี้ตามภาพ</button><div class="section-actions"><button class="button close-dialog">ยกเลิก</button><button class="button primary" id="applyGear">ใช้ในบิลด์ทดลอง ↗</button></div></div>`;}
function syncDraft(){if(!draft)return;draft.enchant=Number($('#editEnchant').value);draft.rarity=$('#editRarity').value;draft.set=$('#editSet').value;draft.coefficient=Number($('#editCoefficient').value);draft.notes=$('#editNotes').value;draft.roleConfirmed=$('#editRoleConfirmed')?.checked===true;}
function handleGearChange(t){if(t.id==='editItem'){changeDraftItem(t.value);return true}if(t.id==='editRarity'){syncDraft();draft.affixes=draft.affixes.slice(0,affixCapacity(draft.rarity));draft=reconcileProfile({...state,gear:[draft]},REPO).gear[0];renderEditor();return true}if(t.dataset.affixChoice!==undefined){syncDraft();const item=REPO.items[draft.itemSlug],rule=item.allowedAffixes.find(r=>r.norm===t.value);if(rule)draft.affixes[Number(t.dataset.affixChoice)]=makeAffix(rule);renderEditor();return true}return false;}

function openPicker(slot){draft=null;pickerSlot=slot;renderPicker();if(!$('#editor').open)$('#editor').showModal()}
function renderPicker(query=''){const used={};state.cards.forEach((s,i)=>{if(i!==pickerSlot)used[s]=(used[s]||0)+1;});const candidates=CATALOG.filter(c=>{const inv=DATA.inventory[c.s],available=(inv?.bank||0)+(inv?.taru||0);return (!ownOnly||available>(used[c.s]||0))&&(!query||[c.n,c.r,c.t,c.e5].some(s=>s.toLowerCase().includes(query.toLowerCase())))});$('#editorContent').innerHTML=`<div class="dialog-head"><div><div class="eyebrow">CARD CATALOG · SLOT ${pickerSlot+1}</div><h2>เลือกการ์ดเข้าบิลด์</h2></div><button class="icon-button close-dialog" aria-label="ปิด">×</button></div><div class="toolbar" style="margin-top:0"><input id="cardSearch" class="search-input" value="${esc(query)}" placeholder="ค้นหาชื่อ เอฟเฟกต์ ภูมิภาค…" aria-label="ค้นหาการ์ด"><label class="switch-label"><input id="ownOnly" type="checkbox" ${ownOnly?'checked':''}> มีในคลัง / ของ Taru เท่านั้น</label></div><p class="note-small">ไม่ยืมใบที่ Karina / Steve ใช้อยู่ · แค็ตตาล็อกทั้งหมดใช้เพื่อทดลอง ไม่ได้ถือว่ามีการ์ดแล้ว</p><div class="picker-list">${candidates.map(c=>{const owned=(DATA.inventory[c.s]?.bank||0)+(DATA.inventory[c.s]?.taru||0);return `<button class="picker-card" data-pick-card="${c.s}" style="--card-color:${colours[c.c]}"><div class="card-glyph">${glyph(c)}</div><div><strong>${esc(c.n)}</strong><p>${esc(owned?c.e5:c.e1)}</p><small>${esc(c.r)} · ${esc(c.c)} · ◆${c.l} · ${owned?`มี ${owned} ใบ · ใช้อยู่ ${used[c.s]||0} ใบ`:'ยังไม่มี · เริ่มทดลอง ★1'}</small></div><span style="margin-left:auto">＋</span></button>`}).join('')||'<div class="empty-state">ไม่พบการ์ดที่ว่างและตรงกับการค้นหา</div>'}</div>`;}
function preset(kind){state.cards=clone(BASE.cards);state.cardStars={};if(kind==='thorn'){state.cards=state.cards.map(s=>s==='shrine_firefly'?'thornling':s==='lamp_wisp'?'shard_thornling':s);state.name='ทดลอง · คู่ Thornling';}else{state.cards=state.cards.map(s=>s==='brass_mimic'?'plate_turtle':s);state.name='ทดลอง · ยืนตี Mini-boss';}state.cards.forEach(s=>state.cardStars[s]=5);commit();toast('เปลี่ยนเฉพาะการ์ดแล้ว · อุปกรณ์และสกิลคงเดิม');}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.hasAttribute('data-gaps')){showDataGaps();return}if(b.dataset.view){setView(b.dataset.view);return}if(b.dataset.go){setView(b.dataset.go);return}if(b.hasAttribute('data-edit')){openEditor(b.dataset.edit);return}if(b.hasAttribute('data-card-slot')){openPicker(Number(b.dataset.cardSlot));return}if(b.dataset.preset){preset(b.dataset.preset);return}if(b.hasAttribute('data-method')||b.id==='methodLink'){e.preventDefault();$('#infoDialog').showModal();return}if(b.classList.contains('close-dialog')){b.closest('dialog').close();draft=null;return}if(b.id==='resetBtn'){state=clone(BASE);commit();toast('กลับไปใช้ชุดเดิมแล้ว');return}if(b.id==='saveBuild'){if(saved.length>=20){toast('บันทึกครบ 20 ชุดแล้ว · ลบชุดที่ไม่ใช้ก่อน');return}saved.push({id:crypto.randomUUID(),profile:clone(state)});persist();render();toast('บันทึกบิลด์ในเบราว์เซอร์นี้แล้ว');return}if(b.dataset.load){const s=saved.find(x=>x.id===b.dataset.load);if(s){state=clone(s.profile);commit();toast('โหลดบิลด์แล้ว')}return}if(b.dataset.deleteBuild){const old=saved.find(x=>x.id===b.dataset.deleteBuild);saved=saved.filter(x=>x.id!==b.dataset.deleteBuild);persist();render();toast('ลบบิลด์ที่บันทึกแล้ว (ชุดทดลองปัจจุบันยังอยู่)');return}if(b.dataset.gearFilter!==undefined){gearFilter=b.dataset.gearFilter;render();return}if(b.dataset.night!==undefined){state.night=b.dataset.night==='true';commit();return}if(b.dataset.skill){const s=state.skills[Number(b.dataset.skill)];s.level=Math.max(0,Math.min(s.max,s.level+Number(b.dataset.step)));commit();return}if(b.dataset.addRow==='affixes'){addDraftAffix();return}if(b.dataset.addRow){syncDraft();draft[b.dataset.addRow].push({key:'atk',value:0,kind:'flat',...(b.dataset.addRow==='affixes'?{name:'ออฟทดลอง',tier:'T8'}:{})});renderEditor();return}if(b.dataset.removeRow){syncDraft();draft[b.dataset.removeRow].splice(Number(b.dataset.row),1);renderEditor();return}if(b.id==='restorePiece'){draft=clone(BASE.gear.find(g=>g.id===draft.id));renderEditor();return}if(b.id==='applyGear'){syncDraft();try{const next=clone(state);next.gear[next.gear.findIndex(g=>g.id===draft.id)]=draft;state=validateProfile(next,BASE,CATALOG);$('#editor').close();draft=null;commit();toast('อัปเดตอุปกรณ์ในบิลด์ทดลองแล้ว')}catch(err){toast(err.message)}return}if(b.dataset.pickCard){const slug=b.dataset.pickCard;state.cards[pickerSlot]=slug;state.cardStars=state.cardStars||{};state.cardStars[slug]=((DATA.inventory[slug]?.bank||0)+(DATA.inventory[slug]?.taru||0))>0?5:1;$('#editor').close();commit();toast('เปลี่ยนการ์ดและคำนวณโบนัสชุดแล้ว');return}if(b.id==='exportBtn'){const output={format:'taru-build-lab',version:1,exportedAt:new Date().toISOString(),profile:state,saved};const url=URL.createObjectURL(new Blob([JSON.stringify(output,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='taru-build-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('ส่งออกบิลด์ JSON แล้ว');return}if(b.id==='importBtn'){$('#importFile').click();return}});
document.addEventListener('change',async e=>{const t=e.target;if(handleGearChange(t))return;if(t.id==='buildName'){state.name=t.value.slice(0,80)||'บิลด์ทดลอง';persist();return}if(t.id==='editEnchant'){syncDraft();draft=reconcileProfile({...state,gear:[draft]},REPO).gear[0];renderEditor();return}if(t.dataset.toggleGear){state.gear.find(g=>g.id===t.dataset.toggleGear).enabled=t.checked;commit();return}if(t.id==='targetSelect'){state.target=t.value;commit();return}if(t.dataset.cardStars){state.cardStars=state.cardStars||{};state.cardStars[t.dataset.cardStars]=Number(t.value);commit();return}if(t.dataset.attr){const n=Number(t.value);state.attrs[t.dataset.attr]=Math.max(0,Math.min(99,Math.round(Number.isFinite(n)?n:0)));commit();return}if(t.dataset.evo){state.skills[Number(t.dataset.evo)].evo=t.value;commit();return}if(t.id==='compareSelect'){compareId=t.value;render();return}if(t.dataset.draftType){const value=t.dataset.field==='value'?Number(t.value):t.value;draft[t.dataset.draftType][Number(t.dataset.row)][t.dataset.field]=value;return}if(t.id==='ownOnly'){ownOnly=t.checked;renderPicker($('#cardSearch').value);return}if(t.id==='importFile'){const f=t.files[0];if(!f)return;try{if(f.size>2000000)throw Error('ไฟล์ใหญ่เกิน 2 MB');const json=JSON.parse(await f.text());const imported=validateProfile(json.profile||json,BASE,CATALOG);const importedSaved=(json.saved||[]).slice(0,20).map(x=>({id:crypto.randomUUID(),profile:validateProfile(x.profile,BASE,CATALOG)}));state=imported;if(importedSaved.length)saved=importedSaved;commit();toast('นำเข้าบิลด์สำเร็จ')}catch(err){toast('นำเข้าไม่ได้: '+err.message)}t.value='';}});
let searchTimer;document.addEventListener('input',e=>{const t=e.target;if(t.id==='editItemSearch'){const q=t.value.trim().toLowerCase();for(const option of document.querySelectorAll('#editItem option'))option.hidden=!!q&&!option.textContent.toLowerCase().includes(q)&&!option.value.toLowerCase().includes(q);}if(t.id==='gearSearch'){const pos=t.selectionStart;search=t.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{render();$('#gearSearch')?.focus();$('#gearSearch')?.setSelectionRange(pos,pos)},180)}if(t.id==='cardSearch'){const q=t.value,pos=t.selectionStart;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{renderPicker(q);$('#cardSearch').focus();$('#cardSearch').setSelectionRange(pos,pos)},160)}if(t.dataset.draftType){draft[t.dataset.draftType][Number(t.dataset.row)][t.dataset.field]=t.dataset.field==='value'?Number(t.value):t.value;}});
for(const d of document.querySelectorAll('dialog'))d.addEventListener('click',e=>{if(e.target===d){const box=d.getBoundingClientRect();if(e.clientX<box.left||e.clientX>box.right||e.clientY<box.top||e.clientY>box.bottom){d.close();draft=null}}});
render();

function mapsView(){return '<div class="section-label"><div><h2>แมพจากการดึงล่าสุด · '+DATA.maps.length+' แมพ</h2><p>Tidehaven Lv 99–113 และ Copperbell Arena · เลือกดู Wiki ต้นทางได้</p></div></div><div class="map-grid">'+DATA.maps.map(m=>'<article class="panel"><div class="panel-head"><div><h2>'+esc(m.name)+'</h2><p>รายละเอียด '+esc(m.lastCrawled)+'</p></div><a href="'+esc(m.sourceUrl)+'" target="_blank" rel="noreferrer">เปิด Wiki ↗</a></div><div class="panel-body"><p class="note-small">'+esc(m.summary.replace(/\[([^\]]+)\]\([^)]*\)/g,'$1').slice(0,450))+'</p>'+m.tables.slice(0,2).map(t=>'<h3>'+esc(t.section)+'</h3><div class="map-table"><table><thead><tr>'+t.header.map(h=>'<th>'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+t.rows.slice(0,8).map(row=>'<tr>'+row.map(c=>'<td>'+esc(c)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>').join('')+'</div></article>').join('')+'</div>';}
